import multiprocessing

import pytest

from hipop.graph import OrientedGraph, make_empty_path, make_path
from hipop.shortest_path import dijkstra, dijkstra_single_source, parallel_dijkstra


# Graph similar to the one generated by function simple_graph() in cpp/tests/sample_graphs.h,
# with no bus layer:
#
# ```
#         5           1.5
#   A --------> B --------> C
#   |           |           |
#  6|           |4          |4
#   |           |           |
#   v           v           v
#   D --------> E --------> F
#        2            3
#
#               I (isolated node)
# ```
def _make_simple_graph() -> OrientedGraph:

    G = OrientedGraph()

    G.add_node("A", 0, 0, "")
    G.add_node("B", 1, 0, "")
    G.add_node("C", 2, 0, "")
    G.add_node("D", 0, 1, "")
    G.add_node("E", 1, 1, "")
    G.add_node("F", 2, 1, "")
    G.add_node("I", 2, 2, "")

    G.add_link("A_B", "A", "B", 1, {"CAR": {"time": 5}}, "CarLayer")
    G.add_link("B_C", "B", "C", 1, {"CAR": {"time": 1.5}}, "CarLayer")
    G.add_link("D_E", "D", "E", 1, {"CAR": {"time": 2}}, "CarLayer")
    G.add_link("E_F", "E", "F", 1, {"CAR": {"time": 3}}, "CarLayer")
    G.add_link("A_D", "A", "D", 1, {"CAR": {"time": 6}}, "CarLayer")
    G.add_link("B_E", "B", "E", 1, {"CAR": {"time": 4}}, "CarLayer")
    G.add_link("C_F", "C", "F", 1, {"CAR": {"time": 4}}, "CarLayer")

    return G


# Test the shortest_path bindings (non-parallel case).
# REMARK: here, the goal is to validate the bindings, not to cover
# all the algorithmic edge cases (these are covered in the C++ tests).
def test_dijkstra() -> None:

    G = _make_simple_graph()

    # Standard cases
    path = dijkstra(G, "A", "E", "time", {"CarLayer": "CAR"})
    assert path == (make_path(G, ["A_D", "D_E"]), 8), "A -> E"
    path = dijkstra(G, "B", "F", "time", {"CarLayer": "CAR"})
    assert path == (make_path(G, ["B_C", "C_F"]), 5.5), "B -> F"
    path = dijkstra(G, "A", "F", "time", {"CarLayer": "CAR"})
    assert path == (make_path(G, ["A_B", "B_C", "C_F"]), 10.5), "A -> F"

    # Edge cases
    path = dijkstra(G, "A", "A", "time", {"CarLayer": "CAR"})
    assert path == (make_empty_path(G, "A"), 0), "Empty path A -> A"
    path = dijkstra(G, "B", "B", "time", {"CarLayer": "CAR"})
    assert path == (make_empty_path(G, "B"), 0), "Empty path B -> B"
    path = dijkstra(G, "A", "I", "time", {"CarLayer": "CAR"})
    assert path is None, "Non-feasible path A -> I"
    path = dijkstra(G, "D", "A", "time", {"CarLayer": "CAR"})
    assert path is None, "Non-feasible path D -> A"


# Test the shortest_path bindings (parallel case, involving OpenMP).
def test_parallel_dijkstra() -> None:

    G = _make_simple_graph()

    origins      = ["A", "B", "A", "A", "B", "A", "D"]
    destinations = ["E", "F", "F", "A", "B", "I", "A"]
    paths = parallel_dijkstra(G, origins, destinations, [{"CarLayer": "CAR"}] * len(origins), "time", multiprocessing.cpu_count())

    assert paths == [
        # Standard cases
        (make_path(G, ["A_D", "D_E"]), 8),
        (make_path(G, ["B_C", "C_F"]), 5.5),
        (make_path(G, ["A_B", "B_C", "C_F"]), 10.5),
        # Edge cases
        (make_empty_path(G, "A"), 0),
        (make_empty_path(G, "B"), 0),
        None,
        None,
    ]


# Test the bindings exposed for dijkstra_single_source and its returned object SameOriginPathTree.
# REMARK: here, the goal is to validate the bindings, not to cover
# all the algorithmic edge cases (these are covered in the C++ tests).
def test_dijkstra_single_source() -> None:

    G = _make_simple_graph()
    tree = dijkstra_single_source(G, "B", "time", {"CarLayer": "CAR"})

    assert tree.origin.id == "B"

    # Destinations
    assert sorted(node.id for node in tree.destinations) == ["B", "C", "E", "F"]
    assert len(tree.destinations) == 4
    assert G.nodes["F"] in tree.destinations
    assert G.nodes["A"] not in tree.destinations

    # Paths
    assert tree.has_path_to(G.nodes["B"])
    assert not tree.has_path_to(G.nodes["A"])
    assert tree.path_to(G.nodes["B"]) == make_empty_path(G, "B"), "Empty path B -> B"
    assert tree.path_to(G.nodes["F"]) == make_path(G, ["B_C", "C_F"]), "B -> F"
    assert tree.find_path_to(G.nodes["E"]) == make_path(G, ["B_E"]), "B -> E"
    assert tree.find_path_to(G.nodes["D"]) is None, "Non-feasible path B -> D"
    with pytest.raises(ValueError, match=r"\[D\]"):
        tree.path_to(G.nodes["D"])
